#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
from jsonschema import Draft202012Validator
ROOT=Path(__file__).resolve().parents[2]
SUITE_PATH=ROOT/"compat/cases/m0-residual-f-misc-contract.json"
SUITE_SCHEMA_PATH=ROOT/"compat/schema/suite.schema.json"
SUITE_ID="m0-residual-f-misc-contract"
FIXTURE="compat/fixtures/m0-residual-f-misc-contract"
CANONICAL_CASES={"m0-residual-f-misc-contract-control": {"command": "genhtml", "arguments": ["--config-file", "control.lcovrc", "--output-directory", "report", "input.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-check-data-consistency": {"command": "genhtml", "arguments": ["--config-file", "check-data-consistency.lcovrc", "--output-directory", "report", "inconsistent.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-demangle-cpp": {"command": "genhtml", "arguments": ["--config-file", "demangle-cpp.lcovrc", "--output-directory", "report", "mangled.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-derive-function-end-line-all-files": {"command": "lcov", "arguments": ["--config-file", "derive-function-end-line-all-files.lcovrc", "-a", "nonc.info", "-o", "out.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-expected-message-count": {"command": "genhtml", "arguments": ["--config-file", "expected-message-count.lcovrc", "--output-directory", "report", "input.info", "--ignore-errors", "source"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-forget-testcase-names": {"command": "lcov", "arguments": ["--config-file", "forget-testcase-names.lcovrc", "-a", "multi_tn.info", "-o", "out.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-info-file-pattern": {"command": "lcov", "arguments": ["--config-file", "info-file-pattern.lcovrc", "-a", "data", "-o", "out.info", "--ignore-errors", "source,unsupported,empty"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-lcov-json-module": {"command": "genhtml", "arguments": ["--config-file", "lcov-json-module.lcovrc", "--output-directory", "report", "input.info", "--ignore-errors", "source,unsupported", "--profile", "/work/prof.json"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-select-script": {"command": "genhtml", "arguments": ["--config-file", "select-script.lcovrc", "--output-directory", "report", "input.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-split-char": {"command": "genhtml", "arguments": ["--config-file", "split-char.lcovrc", "--output-directory", "report", "input.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-suppress-function-aliases": {"command": "genhtml", "arguments": ["--config-file", "suppress-function-aliases.lcovrc", "--output-directory", "report", "aliases.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}, "m0-residual-f-misc-contract-trivial-function-threshold": {"command": "lcov", "arguments": ["--config-file", "trivial-function-threshold.lcovrc", "-a", "trivial_empty.info", "-o", "out.info", "--ignore-errors", "source,unsupported"], "comparisons": [{"dimension": "exit", "normalizer": "exact-v1"}, {"dimension": "filesystem", "normalizer": "exact-v1"}]}}
class Err(RuntimeError): pass
def validate_suite_document(document):
  schema=json.loads(SUITE_SCHEMA_PATH.read_text()); Draft202012Validator.check_schema(schema)
  errs=sorted(Draft202012Validator(schema).iter_errors(document), key=lambda e:list(e.path))
  if errs: raise Err(errs[0].message)
  if document.get("suite_id")!=SUITE_ID or document.get("evidence_scope")!="compatibility" or document.get("schema_version")!=1: raise Err("header")
  cases=document.get("cases")
  if not isinstance(cases,list) or [c.get("id") for c in cases]!=list(CANONICAL_CASES): raise Err("ids")
  for case in cases:
    exp=CANONICAL_CASES[case["id"]]
    if case.get("surface")!="config" or case.get("command")!=exp["command"] or case.get("fixture")!=FIXTURE: raise Err(case["id"])
    if case.get("arguments")!=exp["arguments"] or case.get("comparisons")!=exp["comparisons"]: raise Err(case["id"]+"argv")
    if {i["dimension"] for i in case["comparisons"]}!={"exit","filesystem"}: raise Err("dims")
def validate_committed_suite():
  validate_suite_document(json.loads(SUITE_PATH.read_text()))
if __name__=="__main__":
  validate_committed_suite(); print("OK", SUITE_ID)
